export const ADHKAR_KINDS = ['morning', 'evening'];

export const KIND_META = {
  morning: { title: '🌅 أذكار الصباح', color: 0xD4AF37, intro: 'أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ — ابدأ يومك بذكر الله.' },
  evening: { title: '🌙 أذكار المساء', color: 0x8B5CF6, intro: 'أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ — اختم يومك بذكر الله.' }
};

const CIRCLED = '①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱⑲⑳';
const circled = (n) => CIRCLED[n - 1] ?? `${n}.`;

const countText = (n) => (n === 2 ? 'مرتان' : n >= 3 && n <= 10 ? `${n} مرات` : `${n} مرة`);

function toField(item, label) {
  const note  = item.note ? ` _(${item.note})_` : '';
  const count = item.count > 1 ? `\n🔁 **${countText(item.count)}**` : '';
  // "> " on every line renders a quote bar — a clear visual frame around each dhikr.
  const quoted = item.text.split('\n').map(l => `> ${l}`).join('\n');
  return { name: label.slice(0, 256), value: `${quoted}${note}${count}`.slice(0, 1024) };
}

/** Like toField, but a long text (some du'as are > 1024 chars) is split on word boundaries into continuation fields instead of being cut. */
function toFields(item, label) {
  const note  = item.note ? ` _(${item.note})_` : '';
  const count = item.count > 1 ? `\n🔁 **${countText(item.count)}**` : '';
  const room  = 1024 - note.length - count.length - 4;
  if (item.text.length <= room) return [toField(item, label)];
  const parts = [];
  let rest = item.text;
  while (rest.length > room) {
    let cut = rest.lastIndexOf(' ', room);
    if (cut < room / 2) cut = room;
    parts.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  parts.push(rest);
  return parts.map((t, i) => toField(
    { ...item, text: t, note: i === parts.length - 1 ? item.note : undefined, count: i === parts.length - 1 ? item.count : 1 },
    i === 0 ? label : `${label} (تابع ${i})`));
}

const fieldSize = (f) => f.name.length + f.value.length;

/** Pack fields into embeds: ≤ maxFields fields and ≤ budget characters each (Discord caps an embed at 6000). */
function packFields(fields, budget, maxFields = 24) {
  const pages = [];
  let cur = [], size = 0;
  for (const f of fields) {
    if (cur.length && (cur.length >= maxFields || size + fieldSize(f) > budget)) { pages.push(cur); cur = []; size = 0; }
    cur.push(f); size += fieldSize(f);
  }
  if (cur.length) pages.push(cur);
  return pages;
}

/**
 * @param {'morning'|'evening'} kind
 * @param {{ style?: 'full'|'compact' }} [opts]  compact = key adhkar only, in a single message
 * @returns {{ title: string, description?: string, fields: {name:string,value:string}[] }[]}  one entry per embed, in sending order
 */
export function renderAdhkarPages(kind, { style = 'full', budget = PAGE_LIMIT } = {}) {
  if (!ADHKAR_KINDS.includes(kind)) throw new Error(`Unknown adhkar kind: ${kind}`);
  const meta = KIND_META[kind];
  const list = kind === 'morning' ? MORNING : EVENING;

  if (style === 'compact') {
    const core   = list.filter(i => i.core);
    const fields = core.map((item, i) => toField(item, `${circled(i + 1)} ${item.title}`));
    return packFields(fields, budget).map((f, i) => ({
      title: i === 0 ? meta.title : `${meta.title} (تابع)`,
      description: i === 0 ? `${meta.intro}\n\n📖 **القرآن:** آية الكرسي، ثم الإخلاص والفلق والناس (3 مرات).` : undefined,
      fields: f
    }));
  }

  const quranList   = kind === 'evening' ? [...QURAN, BAQARAH_END] : QURAN;      // the two verses are an evening / night dhikr
  const quranFields = quranList.map(q => toField(q, `📖 ${q.title}`));
  const dhikrFields = list.map((item, i) => toField(item, `${circled(i + 1)} ${item.title}`));

  const out = [];
  packFields(quranFields, budget).forEach((fields, i) => out.push({
    title: i === 0 ? `${meta.title} — القرآن الكريم` : `${meta.title} — القرآن الكريم (تابع)`,
    description: i === 0 ? meta.intro : undefined,
    fields
  }));
  packFields(dhikrFields, budget).forEach((fields, i) => out.push({
    title: i === 0 ? `${meta.title} — الأذكار` : `${meta.title} — الأذكار (تابع)`,
    fields
  }));
  return out;
}

