export const SCATTER_META = { title: '📿 وقفة مع الذكر', color: 0x2E8B57 };
export const SCATTER_KEEP = 8;                                  // how many recent titles the next post avoids

const WINDOWS = { SLEEP: SLEEP_HOURS, WAKE: WAKE_HOURS, MORN: MORNING_HOURS, MEALS: [...BREAKFAST, ...LUNCH_DINNER], IFTAR: [[960, 1260]] };

/** The encyclopedia entries a random post may pick: no duplicates of the lists above, no situational chapters (funeral, hajj…). */
function encyclopediaPool() {
  const out = [];
  for (const cat of HISN) {
    if (!cat.scatter) continue;
    const fresh = cat.items.filter(i => !i.dup && i.text.length <= 900);   // long ones live in the library, not in one-field posts
    fresh.forEach((it, idx) => out.push({
      title: fresh.length > 1 ? `${cat.title} (${idx + 1})` : cat.title,
      icon: cat.icon, count: it.count, text: it.text,
      note: [it.note, it.ref ? `المصدر: ${it.ref}` : 'حصن المسلم'].filter(Boolean).join(' — '),
      ...(cat.when ? { when: WINDOWS[cat.when] } : {})
    }));
  }
  QURAN_DUAS.filter(q => q.text.length <= 900).forEach(q => out.push({ title: `دعاء قرآني: ${q.ref.replace('سورة ', '')}`, icon: '📖', count: 1, text: q.text, note: q.ref }));
  return out;
}

/** Everything the library holds, for browsing: [{ id, title, icon, group, items }] (Hisn chapters + one chapter of Qur'anic du'as). */
export function libraryCategories() {
  const cats = HISN.map(c => ({ id: String(c.id), title: c.title, icon: c.icon, group: c.group,
    items: c.items.map(i => ({ text: i.text, count: i.count, note: [i.note, i.ref ? `المصدر: ${i.ref}` : 'حصن المسلم'].filter(Boolean).join(' — ') })) }));
  cats.push({ id: 'quran', title: 'أدعية قرآنية', icon: '📖', group: 'القرآن الكريم',
    items: QURAN_DUAS.map(q => ({ text: q.text, count: 1, note: q.ref })) });
  return cats;
}

export function renderLibraryPages(cat, { budget = PAGE_LIMIT } = {}) {
  const fields = cat.items.flatMap((it, i) => toFields(it, cat.items.length > 1 ? `${circled(i + 1)} ${cat.title}`.slice(0, 250) : cat.title));
  return packFields(fields, budget).map((f, i) => ({ title: i === 0 ? `${cat.icon} ${cat.title}` : `${cat.icon} ${cat.title} (تابع)`, fields: f }));
}

/** The same chapter, ONE du'a per page (for /azkar: "next" moves to the next du'a of the chapter). A long du'a is split into continuation fields, never cut. */
export function renderLibraryItemPages(cat) {
  const n = cat.items.length;
  return cat.items.map((it, i) => ({
    title: `${cat.icon} ${cat.title}`,
    fields: toFields(it, n > 1 ? `${circled(i + 1)} ${cat.title}`.slice(0, 250) : cat.title)
  }));
}

/** Morning / evening, ONE item per page: the Qur'an first (the two last verses of al-Baqarah in the evening), then the adhkar, in the same order as renderAdhkarPages. */
export function renderAdhkarItemPages(kind) {
  if (!ADHKAR_KINDS.includes(kind)) throw new Error(`Unknown adhkar kind: ${kind}`);
  const meta = KIND_META[kind];
  const list = kind === 'morning' ? MORNING : EVENING;
  const quranList = kind === 'evening' ? [...QURAN, BAQARAH_END] : QURAN;
  const pages = [
    ...quranList.map(q => ({ title: meta.title, fields: [toField(q, `📖 ${q.title}`)] })),
    ...list.map((item, i) => ({ title: meta.title, fields: toFields(item, `${circled(i + 1)} ${item.title}`) }))
  ];
  pages[0].description = meta.intro;
  return pages;
}

function scatterPool() {
  const seen = new Set();
  const anyDhikr = [...MORNING, ...EVENING].filter(i => ANY_TIME.includes(i.title) && !seen.has(`${i.title}|${i.text}`) && seen.add(`${i.title}|${i.text}`));
  const timed = (list, when, icon) => list.filter(i => !ANY_TIME.includes(i.title)).map(i => ({ ...i, when, icon }));
  return [
    ...QURAN.map(q => ({ ...q, count: 1, icon: '📖' })),     // the ×3 of the surahs belongs to morning/evening only
    ...anyDhikr.map(d => ({ ...d, icon: '📿' })),
    ...timed(MORNING, MORNING_HOURS, '🌅'),
    ...timed(EVENING, EVENING_HOURS, '🌙'),
    ...EXTRA,
    ...encyclopediaPool()
  ];
}

const inRanges = (ranges, m) => ranges.some(([a, b]) => m >= a && m <= b);

/** Every item a post can pick at local time `minutes` (all of them when `minutes` is omitted). */
export function scatterCandidates(minutes, weekday) {
  return scatterPool().filter(i =>
    (minutes === null || minutes === undefined || !i.when || inRanges(i.when, minutes)) &&
    (weekday === null || weekday === undefined || !i.days || i.days.includes(weekday)));    // `days` items (Friday…) only on their day
}

/**
 * @param {{ exclude?: string[], rng?: () => number, minutes?: number, weekday?: number }} [opts]  minutes = local time of the post (minutes since midnight) · weekday = local day of the week (0 = Sunday … 5 = Friday)
 * @returns {{ page: { title: string, fields: {name:string,value:string}[] }, title: string }}  `title` = what was picked
 */
export function renderScatterAdhkar({ exclude = [], rng = Math.random, minutes, weekday } = {}) {
  const pool = scatterCandidates(minutes, weekday);
  let fresh = pool.filter(i => !exclude.includes(i.title));
  if (!fresh.length) fresh = pool;
  const item = fresh[Math.floor(rng() * fresh.length)];
  return {
    page: { title: SCATTER_META.title, fields: toFields(item, `${item.icon} ${item.title}`) },
    title: item.title
  };
}
